css:
@import url("https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700&family=Figtree:wght@400;500;600;700&display=swap");
:root{
  --bg:#0E1A24; --surface:#142533; --surface-2:#1B3143; --line:#25405A; --orange:#FF7A1A; --orange-soft:#FFB27A; --ice:#D9F2FF; --green:#39D98A;
  --text:#E4EDF3; --muted:#93AABB;
  --display:"Unbounded", "Arial Black", system-ui, sans-serif;
  --body:"Figtree", system-ui, -apple-system, "Segoe UI", sans-serif;
  --wrap:1220px;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--body);font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block;height:auto}
a{color:inherit}
h1,h2,h3{font-family:var(--display);font-weight:700;margin:0;line-height:1.1;letter-spacing:-.02em;color:#fff}
h3{font-weight:500}
p{margin:0 0 1em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 24px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--orange);color:#111;padding:10px 14px;z-index:99}
:focus-visible{outline:2px solid var(--orange);outline-offset:3px;border-radius:4px}
.grid-bg{background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:56px 56px;background-position:-1px -1px}

.site-header{position:sticky;top:0;z-index:40;background:rgba(14,26,36,.88);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;height:74px}
.logo{display:flex;align-items:center;gap:10px;font-family:var(--display);font-weight:700;font-size:20px;text-decoration:none;color:#fff}
.logo svg{width:32px;height:32px}
.menu{display:flex;gap:30px;list-style:none;margin:0;padding:0}
.menu a{text-decoration:none;color:var(--muted);font-weight:500}.menu a:hover{color:#fff}
.btn{display:inline-flex;align-items:center;gap:10px;padding:13px 24px;border-radius:10px;font-weight:700;text-decoration:none;font-size:16px;font-family:var(--body);border:1px solid transparent;cursor:pointer;transition:background .2s, border-color .2s}
.btn-orange{background:var(--orange);color:#1a0d02}.btn-orange:hover{background:#ff8f3d}
.btn-line{border-color:var(--line);color:#fff;background:transparent}.btn-line:hover{border-color:var(--orange)}
.burger{display:none;background:none;border:1px solid var(--line);border-radius:8px;padding:9px 11px;cursor:pointer}
.burger span{display:block;width:22px;height:2px;background:#fff;margin:4px 0}

/* hero */
.hero{position:relative;padding:90px 0 110px;overflow:hidden}
.hero::before{content:"";position:absolute;inset:0;opacity:.35;mask-image:radial-gradient(ellipse at 70% 30%,#000 10%,transparent 70%);-webkit-mask-image:radial-gradient(ellipse at 70% 30%,#000 10%,transparent 70%)}
.hero-grid{position:relative;display:grid;grid-template-columns:1.1fr .9fr;gap:60px;align-items:center}
.pill{display:inline-flex;align-items:center;gap:10px;border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:7px 16px 7px 10px;font-size:14px;color:var(--muted);margin-bottom:28px}
.pill i{width:10px;height:10px;border-radius:50%;background:var(--green);box-shadow:0 0 0 4px rgba(57,217,138,.2)}
.hero h1{font-size:clamp(38px,5.4vw,70px)}
.hero h1 span{color:var(--orange)}
.hero .lead{font-size:20px;color:var(--muted);max-width:46ch;margin:26px 0 34px}
.hero-actions{display:flex;flex-wrap:wrap;gap:14px}
.hero-trust{display:flex;gap:32px;margin-top:44px;flex-wrap:wrap}
.hero-trust div b{display:block;font-family:var(--display);font-size:28px;color:#fff}
.hero-trust div span{font-size:14px;color:var(--muted)}

.console{background:var(--surface);border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:0 40px 80px -40px rgba(0,0,0,.7)}
.console-top{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid var(--line);font-size:14px;color:var(--muted)}
.dots{display:flex;gap:7px}.dots i{width:11px;height:11px;border-radius:50%;background:var(--line)}
.console-img{position:relative}
.console-img img{width:100%;aspect-ratio:16/8;object-fit:cover}
.console-img::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 40%,var(--surface))}
.status{padding:6px 20px 22px}
.srow{display:grid;grid-template-columns:130px 1fr 66px;gap:14px;align-items:center;padding:9px 0;border-bottom:1px dashed var(--line);font-size:14px}
.srow:last-child{border-bottom:0}
.srow b{font-weight:600;color:#fff}
.bars{display:flex;gap:2px;height:22px}
.bars i{flex:1;background:var(--green);border-radius:2px;opacity:.85}
.bars i.w{background:var(--orange)}
.srow em{font-style:normal;color:var(--green);text-align:right;font-weight:600}

/* logos */
.logos{border-block:1px solid var(--line);padding:30px 0}
.logos .wrap{display:flex;align-items:center;justify-content:space-between;gap:30px;flex-wrap:wrap}
.logos p{margin:0;color:var(--muted);font-size:15px}
.logo-row{display:flex;gap:44px;flex-wrap:wrap;align-items:center}
.logo-row span{font-family:var(--display);font-size:19px;color:#5f7a8f;letter-spacing:.02em}

section{padding:110px 0}
.head{max-width:760px;margin-bottom:56px}
.head h2{font-size:clamp(32px,4vw,52px)}
.head p{color:var(--muted);font-size:19px;margin-top:18px}
.kicker{color:var(--orange);font-weight:700;font-size:15px;margin-bottom:14px;display:block}

.svc-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.svc{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:32px;transition:border-color .25s, transform .25s}
.svc:hover{border-color:var(--orange);transform:translateY(-4px)}
.svc .ico{width:50px;height:50px;border-radius:12px;background:rgba(255,122,26,.12);color:var(--orange);display:grid;place-items:center;margin-bottom:22px}
.svc h3{font-size:21px;margin-bottom:12px}
.svc p{color:var(--muted);font-size:16px;margin:0 0 16px}
.svc ul{list-style:none;padding:0;margin:0;font-size:15px}
.svc li{padding:6px 0 6px 22px;position:relative;color:#c3d3de}
.svc li::before{content:"";position:absolute;left:0;top:14px;width:10px;height:2px;background:var(--orange)}

/* sla band */
.sla{background:var(--ice);color:#0E1A24}
.sla h2,.sla h3{color:#0E1A24}
.sla .kicker{color:#C2530A}
.sla-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center}
.sla-photo{border-radius:18px;overflow:hidden;position:relative}
.sla-photo img{aspect-ratio:5/4;object-fit:cover;width:100%}
.sla-list{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:36px}
.sla-list b{font-family:var(--display);font-size:40px;display:block;line-height:1;color:#0E1A24}
.sla-list span{color:#3c566a;font-size:15px}
.sla p{color:#3c566a;font-size:18px}

/* industries */
.ind-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.ind{position:relative;border-radius:16px;overflow:hidden;min-height:300px;display:flex;align-items:flex-end}
.ind img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:saturate(.7) brightness(.8)}
.ind::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(14,26,36,.1),rgba(14,26,36,.95))}
.ind div{position:relative;z-index:1;padding:24px}
.ind h3{font-size:19px;margin-bottom:6px}
.ind p{font-size:15px;color:#c3d3de;margin:0}

.stack{display:flex;flex-wrap:wrap;gap:10px;margin-top:40px}
.stack span{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:8px 16px;font-size:15px;color:#c3d3de}

/* process */
.process{background:var(--surface)}
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;counter-reset:n}
.step{border-top:3px solid var(--line);padding-top:24px;counter-increment:n}
.step:first-child{border-color:var(--orange)}
.step::before{content:"Week " counter(n);font-weight:700;color:var(--orange);font-size:14px;display:block;margin-bottom:10px}
.step h3{font-size:20px;margin-bottom:10px}
.step p{color:var(--muted);font-size:16px;margin:0}

/* testimonial */
.quote{display:grid;grid-template-columns:.8fr 1.2fr;gap:60px;align-items:center}
.quote figure{margin:0;border-radius:18px;overflow:hidden}
.quote figure img{aspect-ratio:1/1;object-fit:cover;width:100%}
.quote blockquote{margin:0}
.quote blockquote p{font-family:var(--display);font-weight:500;font-size:clamp(22px,2.6vw,32px);line-height:1.35;color:#fff}
.quote cite{font-style:normal;color:var(--muted);display:block;margin-top:24px}
.quote cite b{color:#fff;display:block;font-size:18px}

/* pricing */
.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.plan{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:34px;display:flex;flex-direction:column}
.plan.hot{border:2px solid var(--orange);background:linear-gradient(180deg,#1f2f3c,var(--surface) 40%)}
.plan h3{font-size:22px}
.plan .price{font-family:var(--display);font-size:46px;color:#fff;margin:18px 0 2px}
.plan .price small{font-family:var(--body);font-size:16px;color:var(--muted)}
.plan > p{color:var(--muted);font-size:15px}
.plan ul{list-style:none;padding:0;margin:14px 0 28px;font-size:15px}
.plan li{padding:9px 0;border-bottom:1px solid var(--line);color:#c3d3de}
.plan li::before{content:"✓";color:var(--orange);font-weight:700;margin-right:10px}
.plan .btn{margin-top:auto;justify-content:center}

/* faq */
.faq-wrap{max-width:860px}
details{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:22px 26px;margin-bottom:12px}
summary{cursor:pointer;list-style:none;font-weight:700;font-size:19px;display:flex;justify-content:space-between;gap:20px;color:#fff}
summary::-webkit-details-marker{display:none}
summary::after{content:"+";color:var(--orange);font-size:24px;line-height:1}
details[open] summary::after{content:"−"}
details p{color:var(--muted);margin:14px 0 0}

/* cta */
.cta{position:relative;overflow:hidden}
.cta-box{position:relative;background:var(--orange);color:#1a0d02;border-radius:24px;padding:64px;display:grid;grid-template-columns:1.2fr .8fr;gap:48px;align-items:center}
.cta-box h2{color:#1a0d02;font-size:clamp(30px,3.8vw,48px)}
.cta-box p{font-size:18px;margin:18px 0 0}
.cta-box form{background:#fff;border-radius:16px;padding:26px;display:grid;gap:12px}
.cta-box label{font-weight:700;font-size:14px;color:#0E1A24}
.cta-box input,.cta-box select{width:100%;font:inherit;padding:12px 14px;border:1px solid #d4dde4;border-radius:10px;color:#0E1A24;margin-top:4px}
.cta-box .btn{background:#0E1A24;color:#fff;justify-content:center}

footer{border-top:1px solid var(--line);padding:64px 0 30px;color:var(--muted);font-size:15px}
.foot{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:40px;margin-bottom:48px}
footer h3{font-family:var(--body);font-weight:700;font-size:16px;margin-bottom:14px}
footer ul{list-style:none;padding:0;margin:0}footer li{margin-bottom:8px}
footer a{text-decoration:none}footer a:hover{color:var(--orange)}
.legal{border-top:1px solid var(--line);padding-top:24px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}

@media (max-width:1000px){
  .menu,.nav .btn{display:none}.burger{display:block}
  .menu.open{display:flex;flex-direction:column;position:absolute;top:74px;left:0;right:0;background:var(--bg);padding:22px 24px;border-bottom:1px solid var(--line);gap:16px}
  .hero-grid,.sla-grid,.quote,.cta-box{grid-template-columns:1fr}
  .svc-grid,.plans{grid-template-columns:1fr 1fr}
  .ind-grid,.steps{grid-template-columns:1fr 1fr}
  .foot{grid-template-columns:1fr 1fr}
  .cta-box{padding:40px}
}
@media (max-width:620px){
  body{font-size:16px}
  section{padding:76px 0}
  .svc-grid,.plans,.ind-grid,.steps,.sla-list,.foot{grid-template-columns:1fr}
  .srow{grid-template-columns:96px 1fr 54px;font-size:13px}
  .cta-box{padding:28px}
}

javascript:
const burger=document.querySelector('.burger'),menu=document.getElementById('menu');
  burger.addEventListener('click',()=>{const o=menu.classList.toggle('open');burger.setAttribute('aria-expanded',o)});
  menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.classList.remove('open');burger.setAttribute('aria-expanded',false)}));
  // uptime rows
  const rows=[['Email & chat','100%'],['Cloud servers','99.99%'],['Office network','99.97%'],['Backups','100%']];
  document.getElementById('status').innerHTML=rows.map(([n,u],r)=>{
    let bars='';for(let i=0;i<30;i++){bars+='<i'+((r===2&&i===17)||(r===1&&i===8)?' class="w"':'')+'></i>'}
    return `<div class="srow"><b>${n}</b><div class="bars" aria-hidden="true">${bars}</div><em>${u}</em></div>`}).join('');
  document.getElementById('yr').textContent=new Date().getFullYear();
